from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1];HERE=ROOT/'coupling_factorial'
def main():
 # Prior drafts are regenerated by their original script; new context is added.
 import subprocess,sys
 subprocess.run([sys.executable,str(ROOT/'envelope_selection/make_submission.py')],check=True)
 s=json.loads((HERE/'results/summary.json').read_text());p=ROOT/'submission/cover_letter_draft.md';t=p.read_text();text='An independently locked four-cell follow-up supplies the same endpoint screen to graphical and incremental reaction-path engines. It preserves signed reaction-path endpoint differences and separates whole-policy screening effects from implementation effects. The study retains all four planned contrasts, certification rates and unresolved outcomes. A positive-drift count bound and a fixed-reservation break-even result identify sufficient screening conditions; neither is claimed as universal runtime dominance. '
 z=[c for c in s['contrasts'] if c['matched_quality_efficiency']]
 text+=('The follow-up meets its strict equal-quality cost criterion for '+', '.join(c['name'].replace('_',' ') for c in z)+'.' if z else 'None of its four contrasts meets the strict matched-certified-quality efficiency criterion.')
 rtc=next(c for c in s['contrasts'] if c['name']=='screen_rtc')['wall_seconds'];plain=next(c for c in s['contrasts'] if c['name']=='engine_plain')['wall_seconds']
 text+=f" The prespecified graph-level geometric RTC screening ratio is {rtc['ratio']:.3f} [{rtc['ci'][0]:.3f}, {rtc['ci'][1]:.3f}]; arithmetic mean times are {s['methods']['rtc_envelope']['mean_wall']:.3f} s with screening and {s['methods']['rtc']['mean_wall']:.3f} s without, so this is not an aggregate-throughput improvement. The unscreened RTC/graphical geometric ratio is {plain['ratio']:.3f} [{plain['ci'][0]:.3f}, {plain['ci'][1]:.3f}], with both methods certifying 96/96 queries."
 t=t.replace('The study also retains',text+'\n\nThe study also retains');p.write_text(t)
 p=ROOT/'submission/submission_notes.md';p.write_text(p.read_text()+'\nLatest reproduction: `python reproduce_factorial.py --analysis-only`. The earlier reproduction scripts remain for the preceding releases and should not be used to regenerate the enlarged final article. The bibliography is unchanged under the earlier user constraint; the verified nearest-side-information records in coupling_factorial/reports/positioning.md should be resolved before submission.\n')
if __name__=='__main__':main()
